import type { Plugin, PluginListenerHandle } from '@capacitor/core';

export interface AnalysisOptions {
  values: number[];
}

export interface AnalysisResult {
  count: number;
  sum: number;
  mean: number;
  min: number;
  max: number;
  stdDev: number;
}

export interface AnalysisCompleteEvent {
  sequence: number;
  mean: number;
}

export interface RunningTotal {
  total: number;
}

export interface MetricsAnalyzerPlugin extends Plugin {
  analyze(options: AnalysisOptions): Promise<AnalysisResult>;
  getRunningTotal(): Promise<RunningTotal>;
  addListener(
    eventName: 'analysisComplete',
    listenerFunc: (event: AnalysisCompleteEvent) => void,
  ): Promise<PluginListenerHandle> & PluginListenerHandle;
}

import { WebPlugin } from '@capacitor/core';
import type {
  AnalysisCompleteEvent,
  AnalysisOptions,
  AnalysisResult,
  MetricsAnalyzerPlugin,
  RunningTotal,
} from './definitions';

export class MetricsAnalyzerWeb
  extends WebPlugin
  implements MetricsAnalyzerPlugin
{
  private analyzeCount = 0;

  async analyze(options: AnalysisOptions): Promise<AnalysisResult> {
    const values = options?.values ?? [];
    const count = values.length;

    // Bump the analysis counter and emit the analysisComplete event BEFORE
    // resolving so any listener registered by the time it executes receives it.
    this.analyzeCount += 1;

    if (count === 0) {
      const emptyResult: AnalysisResult = {
        count: 0,
        sum: 0,
        mean: 0,
        min: 0,
        max: 0,
        stdDev: 0,
      };

      const event: AnalysisCompleteEvent = {
        sequence: this.analyzeCount,
        mean: 0,
      };
      this.notifyListeners('analysisComplete', event);

      return emptyResult;
    }

    let sum = 0;
    let min = values[0]!;
    let max = values[0]!;
    for (let i = 0; i < count; i++) {
      const v = values[i]!;
      sum += v;
      if (v < min) min = v;
      if (v > max) max = v;
    }
    const mean = sum / count;

    let squaredDeviations = 0;
    for (let i = 0; i < count; i++) {
      const diff = values[i]! - mean;
      squaredDeviations += diff * diff;
    }
    // Population standard deviation: divide by N (not N - 1).
    const stdDev = Math.sqrt(squaredDeviations / count);

    const result: AnalysisResult = {
      count,
      sum,
      mean,
      min,
      max,
      stdDev,
    };

    const event: AnalysisCompleteEvent = {
      sequence: this.analyzeCount,
      mean,
    };
    this.notifyListeners('analysisComplete', event);

    return result;
  }

  async getRunningTotal(): Promise<RunningTotal> {
    return { total: this.analyzeCount };
  }
}

