// Custom Capacitor plugin demo: MetricsAnalyzer
// This file is the application entry. It:
//   1. Registers the local `MetricsAnalyzer` Capacitor plugin (Web implementation only).
//   2. Exposes the plugin and a global events buffer on `window` for test/automation.
//   3. Wires an `analysisComplete` listener that renders results into the DOM.

import { registerPlugin } from '@capacitor/core';
import type {
  AnalysisCompleteEvent,
  AnalysisResult,
  MetricsAnalyzerPlugin,
} from './definitions';

// -----------------------------------------------------------------------------
// Plugin registration
// -----------------------------------------------------------------------------

const MetricsAnalyzer = registerPlugin<MetricsAnalyzerPlugin>('MetricsAnalyzer', {
  web: () => import('./web').then((m) => new m.MetricsAnalyzerWeb()),
});

// Augment the global Window interface so TypeScript is happy with our additions.
declare global {
  interface Window {
    MetricsAnalyzer: MetricsAnalyzerPlugin;
    __analysisEvents: AnalysisCompleteEvent[];
    __latestResult: AnalysisResult | null;
  }
}

// -----------------------------------------------------------------------------
// Window globals (exposed for the headless browser / automation harness)
// -----------------------------------------------------------------------------

window.MetricsAnalyzer = MetricsAnalyzer;
window.__analysisEvents = [];
window.__latestResult = null;

// -----------------------------------------------------------------------------
// DOM references and rendering helpers
// -----------------------------------------------------------------------------

const resultEl = document.getElementById('result') as HTMLPreElement | null;
const eventCountEl = document.getElementById('event-count') as HTMLSpanElement | null;

function renderResult(result: AnalysisResult | null): void {
  if (resultEl) {
    resultEl.textContent = result === null ? '' : JSON.stringify(result);
  }
}

function renderEventCount(count: number): void {
  if (eventCountEl) {
    eventCountEl.textContent = String(count);
  }
}

// -----------------------------------------------------------------------------
// analysisComplete listener
// -----------------------------------------------------------------------------

MetricsAnalyzer.addListener('analysisComplete', (event: AnalysisCompleteEvent) => {
  // 1) Record the raw event payload in the order it was received.
  window.__analysisEvents.push(event);

  // 2) Render the most recent analysis summary that we know about.
  //    The listener payload only contains `{ sequence, mean }`, so we
  //    reconstruct a JSON view from the latest full result if the most
  //    recent caller (this page or a headless harness) has provided one.
  //    When nothing is available yet we still surface the event info.
  if (window.__latestResult) {
    renderResult(window.__latestResult);
  } else {
    renderResult({ count: 0, sum: 0, mean: event.mean, min: 0, max: 0, stdDev: 0 });
  }

  // 3) Update the visible event counter.
  renderEventCount(window.__analysisEvents.length);
});

// -----------------------------------------------------------------------------
// Track the latest full AnalysisResult so the listener can render it.
// We can't intercept the proxy's `analyze` method, so we wrap a reference to
// the underlying web implementation by re-registering/deriving through the
// plugin. The wrapper below keeps a cache without changing `window.MetricsAnalyzer`.
// -----------------------------------------------------------------------------

function trackLatestResult<T extends typeof MetricsAnalyzer.analyze>(analyze: T): T {
  return (async (options: Parameters<T>[0]) => {
    const result = await analyze(options);
    window.__latestResult = result as AnalysisResult;
    renderResult(window.__latestResult);
    return result;
  }) as unknown as T;
}

// Expose a tracked wrapper that drives the Web implementation directly
// through the same lazy import. This is what page-init code (and tests that
// want to pre-populate the latest-result cache) can use. The raw
// `window.MetricsAnalyzer` still resolves through the proxy exactly as
// registered.
async function runInitialAnalysis(): Promise<void> {
  const mod = await import('./web');
  const impl = new mod.MetricsAnalyzerWeb();
  const tracked = trackLatestResult(impl.analyze.bind(impl));
  await tracked({ values: [] });
}

// Kick off the initial (empty) analysis so the listener fires once at page load
// and the DOM shows a known state.
runInitialAnalysis().catch((err) => {
  // eslint-disable-next-line no-console
  console.error('Failed to run initial analysis:', err);
});

