import { WebPlugin } from '@capacitor/core';
import type {
  AnalysisCompleteEvent,
  AnalysisOptions,
  AnalysisResult,
  MetricsAnalyzerPlugin,
  RunningTotal,
} from './definitions';

// Module-level cache of the most recent analysis result. The Capacitor proxy
// only creates one instance of this Web implementation, but we still keep the
// state in module scope so consumers in the entry code (e.g. a DOM-rendering
// listener) can read it back even without going through the proxy again.
let lastResult: AnalysisResult | null = null;

/** Read the latest `analyze({ values })` result from this web implementation. */
export function getMetricsAnalyzerLatestResult(): AnalysisResult | null {
  return lastResult;
}

/** Test helper to clear internal state between runs. */
export function __resetMetricsAnalyzerState(): void {
  lastResult = null;
  analyzeCounter = 0;
}

let analyzeCounter = 0;

export class MetricsAnalyzerWeb
  extends WebPlugin
  implements MetricsAnalyzerPlugin
{
  async analyze(options: AnalysisOptions): Promise<AnalysisResult> {
    const values = options?.values ?? [];
    const count = values.length;

    // Bump the analysis counter before notifying so listeners observe a
    // 1-based sequence number that matches the order in which `analyze`
    // calls resolve.
    analyzeCounter += 1;

    let result: AnalysisResult;
    if (count === 0) {
      result = {
        count: 0,
        sum: 0,
        mean: 0,
        min: 0,
        max: 0,
        stdDev: 0,
      };
    } else {
      let sum = 0;
      let min = values[0]!;
      let max = values[0]!;
      for (let i = 0; i < count; i++) {
        const v = values[i]!;
        sum += v;
        if (v < min) min = v;
        if (v > max) max = v;
      }
      const mean = sum / count;

      let squaredDeviations = 0;
      for (let i = 0; i < count; i++) {
        const diff = values[i]! - mean;
        squaredDeviations += diff * diff;
      }
      // Population standard deviation: divide by N (not N - 1).
      const stdDev = Math.sqrt(squaredDeviations / count);

      result = {
        count,
        sum,
        mean,
        min,
        max,
        stdDev,
      };
    }

    // Cache the latest result so other code (like a DOM listener that only
    // receives `{ sequence, mean }` in the event payload) can read the full
    // analysis back without an extra `analyze` call.
    lastResult = result;

    const event: AnalysisCompleteEvent = {
      sequence: analyzeCounter,
      mean: result.mean,
    };
    this.notifyListeners('analysisComplete', event);

    return result;
  }

  async getRunningTotal(): Promise<RunningTotal> {
    return { total: analyzeCounter };
  }
}

// Custom Capacitor plugin demo: MetricsAnalyzer
// This file is the application entry. It:
//   1. Registers the local `MetricsAnalyzer` Capacitor plugin (Web only).
//   2. Exposes the plugin and a global events buffer on `window` for automation.
//   3. Wires an `analysisComplete` listener that renders results into the DOM.

import { registerPlugin } from '@capacitor/core';
import type {
  AnalysisCompleteEvent,
  AnalysisResult,
  MetricsAnalyzerPlugin,
} from './definitions';
import { getMetricsAnalyzerLatestResult } from './web';

// -----------------------------------------------------------------------------
// Plugin registration
// -----------------------------------------------------------------------------

const MetricsAnalyzer = registerPlugin<MetricsAnalyzerPlugin>('MetricsAnalyzer', {
  web: () => import('./web').then((m) => new m.MetricsAnalyzerWeb()),
});

// Augment the global Window interface so TypeScript is happy with our additions.
declare global {
  interface Window {
    MetricsAnalyzer: MetricsAnalyzerPlugin;
    __analysisEvents: AnalysisCompleteEvent[];
  }
}

// -----------------------------------------------------------------------------
// Window globals (exposed for the headless browser / automation harness)
// -----------------------------------------------------------------------------

window.MetricsAnalyzer = MetricsAnalyzer;
window.__analysisEvents = [];

// -----------------------------------------------------------------------------
// DOM references and rendering helpers
// -----------------------------------------------------------------------------

const resultEl = document.getElementById('result') as HTMLPreElement | null;
const eventCountEl = document.getElementById('event-count') as HTMLSpanElement | null;

function renderResult(result: AnalysisResult | null): void {
  if (resultEl) {
    resultEl.textContent = result === null ? '' : JSON.stringify(result);
  }
}

function renderEventCount(count: number): void {
  if (eventCountEl) {
    eventCountEl.textContent = String(count);
  }
}

renderEventCount(0);
renderResult(null);

// -----------------------------------------------------------------------------
// analysisComplete listener
// -----------------------------------------------------------------------------

MetricsAnalyzer.addListener('analysisComplete', (event: AnalysisCompleteEvent) => {
  // 1) Record the raw event payload in the order it was received.
  window.__analysisEvents.push(event);

  // 2) Render the most recent analysis result. The event payload only carries
  //    `{ sequence, mean }`, so we read the full result back from the web
  //    implementation's module-scoped cache (kept in sync inside `analyze()`).
  renderResult(getMetricsAnalyzerLatestResult());

  // 3) Update the visible event counter.
  renderEventCount(window.__analysisEvents.length);
});

import type { AnalysisResult } from './definitions';

/**
 * Tiny module shared between the entry code and the Web implementation so
 * the listener in `main.ts` can read the most recent `analyze({values})`
 * result without having to import the entire plugin (which is loaded
 * lazily through `registerPlugin`).
 */
let lastResult: AnalysisResult | null = null;

export function setMetricsAnalyzerLatestResult(result: AnalysisResult): void {
  lastResult = result;
}

export function getMetricsAnalyzerLatestResult(): AnalysisResult | null {
  return lastResult;
}

export function clearMetricsAnalyzerLatestResult(): void {
  lastResult = null;
}

